<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\OperatingUnitService;
use EventMenu\Services\RefundService;
use EventMenu\Support\OperationalDiagnostics;
use EventMenu\Support\UiVocabulary;

Auth::requirePermission('payments.manage');$tenantId=em_require_tenant();
try{$unit=(new OperatingUnitService())->requireCurrent();}catch(Throwable$e){$safe=OperationalDiagnostics::userFacing($e,'Não foi possível carregar os pagamentos desta unidade.','web.payments.unit');em_header('Pagamentos','payments');?><div class="alert error"><?= Security::e($safe['message']) ?></div><?php em_footer();return;}$unitId=(int)$unit['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    try{
        if($action==='refund'){
            Auth::requirePermission('refunds.manage');$r=(new RefundService())->requestFull((int)($_POST['payment_id']??0),(string)($_POST['reason']??''));
            em_flash($r['status']==='completed'?'ok':'error',$r['status']==='completed'?'Estorno concluído.':'Estorno solicitado. A confirmação pode levar alguns instantes.');
        }elseif($action==='reconcile-refund'){
            Auth::requirePermission('refunds.manage');$r=(new RefundService())->reconcile((int)($_POST['refund_id']??0));
            em_flash($r['status']==='completed'?'ok':'error',$r['status']==='completed'?'Estorno confirmado e concluído.':'O estorno ainda está aguardando confirmação.');
        }else throw new RuntimeException('Ação inválida.');
    }catch(Throwable$e){$safe=OperationalDiagnostics::userFacing($e,'Não foi possível concluir a operação financeira. Tente novamente.','web.payments.action',['action'=>$action]);em_flash('error',$safe['message']);}
    em_go('payments');
}
$method=trim((string)($_GET['method']??($_GET['provider']??'')));$status=trim((string)($_GET['status']??''));$q=trim((string)($_GET['q']??''));
$sql='SELECT p.*,o.status order_status,o.payment_status order_payment_status,c.name customer_name,r.id refund_id,r.status refund_status,r.reason refund_reason FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN refunds r ON r.tenant_id=p.tenant_id AND r.payment_id=p.id WHERE p.tenant_id=? AND o.unit_id=?';$args=[$tenantId,$unitId];
if($method==='pix')$sql.=' AND p.provider IN ("pagbank","mercadopago")';elseif($method==='cash')$sql.=' AND p.provider="manual"';elseif($method==='card')$sql.=' AND p.provider="stripe"';elseif(in_array($method,['pagbank','mercadopago','manual','stripe'],true)){$sql.=' AND p.provider=?';$args[]=$method;}
if($status!==''){$sql.=' AND p.status=?';$args[]=$status;}if($q!==''){if(ctype_digit(ltrim($q,'#'))){$sql.=' AND o.id=?';$args[]=(int)ltrim($q,'#');}else{$sql.=' AND (c.name LIKE ? OR p.provider_payment_id LIKE ?)';$like='%'.$q.'%';$args[]=$like;$args[]=$like;}}$sql.=' ORDER BY p.id DESC LIMIT 250';$s=$pdo->prepare($sql);$s->execute($args);$payments=$s->fetchAll();
$stats=[];$statSql=[
 'paid'=>'SELECT COALESCE(SUM(p.amount_cents),0) FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="paid"',
 'pending'=>'SELECT COUNT(*) FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status IN ("created","pending","authorized")',
 'failed'=>'SELECT COUNT(*) FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="failed"',
 'refunded'=>'SELECT COALESCE(SUM(p.amount_cents),0) FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="refunded"',
 'duplicates'=>'SELECT COUNT(*) FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="duplicate_paid"',
 'duplicate_amount'=>'SELECT COALESCE(SUM(p.amount_cents),0) FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="duplicate_paid"'];foreach($statSql as$k=>$sqlStat){$x=$pdo->prepare($sqlStat);$x->execute([$tenantId,$unitId]);$stats[$k]=$x->fetchColumn();}
$providerTotals=[];$pt=$pdo->prepare('SELECT p.provider,COALESCE(SUM(p.amount_cents),0) amount FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="paid" GROUP BY p.provider ORDER BY amount DESC');$pt->execute([$tenantId,$unitId]);foreach($pt->fetchAll()as$row)$providerTotals[(string)$row['provider']]=(int)$row['amount'];$methodTotals=[];foreach($providerTotals as$providerName=>$amount){$label=UiVocabulary::paymentMethod($providerName);$methodTotals[$label]=($methodTotals[$label]??0)+$amount;}$methodGrand=max(1,array_sum($methodTotals));
$daily=[];$dp=$pdo->prepare('SELECT p.created_at,p.amount_cents FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="paid" ORDER BY p.id DESC LIMIT 500');$dp->execute([$tenantId,$unitId]);foreach($dp->fetchAll()as$row){$key=date('d/m',strtotime((string)$row['created_at']));$daily[$key]=($daily[$key]??0)+(int)$row['amount_cents'];}$daily=array_slice(array_reverse($daily,true),-8,null,true);$dailyMax=max(1,$daily?max($daily):1);
$webhooks=[];if(Auth::can('audit.view')){$w=$pdo->prepare('SELECT * FROM webhook_events WHERE tenant_id=? ORDER BY id DESC LIMIT 100');$w->execute([$tenantId]);$webhooks=$w->fetchAll();}
em_header('Pagamentos','payments');
?>
<section class="page-hero"><div><span class="eyebrow">PAGAMENTOS · <?= Security::e($unit['name']) ?></span><h2>Recebimentos e estornos</h2><p>Acompanhe o que foi recebido, o que ainda aguarda confirmação e operações que precisam de atenção.</p></div><div class="hero-actions"><a class="button secondary" href="<?= Security::e(app_url('?route=cash')) ?>">Turno de caixa</a><a class="button secondary" href="<?= Security::e(app_url('?route=reports')) ?>">Relatórios</a></div></section>
<section class="grid finance-summary"><div class="card metric"><span class="muted">Recebido</span><strong><?= em_money($stats['paid']) ?></strong></div><div class="card metric"><span class="muted">Estornado</span><strong><?= em_money($stats['refunded']) ?></strong></div><div class="card metric"><span class="muted">Aguardando confirmação</span><strong><?= (int)$stats['pending'] ?></strong></div><div class="card metric"><span class="muted">Precisam de atenção</span><strong><?= (int)$stats['failed'] ?></strong></div></section>
<?php if((int)$stats['duplicates']>0):?><div class="alert error" style="margin-top:14px"><strong>Atenção:</strong> foram identificados <?= (int)$stats['duplicates'] ?> pagamento(s) duplicado(s), totalizando <?= em_money($stats['duplicate_amount']) ?> nesta unidade. Esses valores não serão aplicados novamente ao pedido.</div><?php endif;?>
<section class="finance-methods" style="margin-top:14px"><article class="card"><div class="section-head"><div><span class="eyebrow">EVOLUÇÃO</span><h2>Recebimentos recentes</h2></div></div><div class="chart-bars"><?php if(!$daily):?><div class="muted">Ainda não há pagamentos confirmados.</div><?php else:foreach($daily as$label=>$value):$height=max(7,(int)round($value*100/$dailyMax));?><div class="chart-bar" style="height:<?= $height ?>%" title="<?= Security::e($label.' · '.em_money($value)) ?>"><span><?= Security::e($label) ?></span></div><?php endforeach;endif;?></div></article><article class="card"><div class="section-head"><div><span class="eyebrow">FORMAS DE PAGAMENTO</span><h2>Como os clientes pagaram</h2></div></div><div class="method-list"><?php foreach($methodTotals as$name=>$amount):$pct=(int)round($amount*100/$methodGrand);?><div class="method-row"><span><?= Security::e($name) ?></span><div class="channel-track"><div class="channel-fill" style="width:<?= $pct ?>%"></div></div><strong><?= $pct ?>%</strong></div><?php endforeach;?><?php if(!$methodTotals):?><span class="muted">Sem pagamentos confirmados.</span><?php endif;?></div></article></section>
<section class="card" style="margin-top:14px"><div class="section-head"><div><span class="eyebrow">MOVIMENTAÇÕES · <?= Security::e($unit['name']) ?></span><h2>Pagamentos recentes</h2></div></div><form method="get" class="form-grid" style="margin-bottom:12px"><input type="hidden" name="route" value="payments"><label class="span-2">Buscar pedido ou cliente<input name="q" value="<?= Security::e($q) ?>" placeholder="#123 ou nome do cliente"></label><label>Forma de pagamento<select name="method"><option value="">Todas</option><option value="pix"<?= em_selected($method,'pix') ?>>PIX</option><option value="card"<?= em_selected($method,'card') ?>>Cartão</option><option value="cash"<?= em_selected($method,'cash') ?>>Dinheiro</option></select></label><label>Situação<select name="status"><option value="">Todas</option><?php foreach(['created','pending','authorized','paid','duplicate_paid','failed','cancelled','refunded','partially_refunded']as$st):?><option value="<?= $st ?>"<?= em_selected($status,$st) ?>><?= Security::e(UiVocabulary::paymentStatus($st)) ?></option><?php endforeach;?></select></label><div class="actions span-2"><button class="secondary">Filtrar</button><a class="button secondary" href="<?= Security::e(app_url('?route=payments')) ?>">Limpar</a></div></form><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Pedido</th><th>Cliente</th><th>Forma</th><th>Valor</th><th>Situação</th><th>Ações</th></tr></thead><tbody><?php foreach($payments as$p):?><tr><td><?= Security::e($p['created_at']??'') ?></td><td><a href="<?= Security::e(app_url('?route=orders&view='.(int)$p['order_id'])) ?>"><strong>#<?= (int)$p['order_id'] ?></strong></a></td><td><?= Security::e($p['customer_name']??'—') ?></td><td><?= Security::e(UiVocabulary::paymentMethod((string)$p['provider'])) ?></td><td><strong><?= em_money($p['amount_cents']) ?></strong></td><td><span class="badge"><?= Security::e(UiVocabulary::paymentStatus((string)$p['status'])) ?></span><?php if($p['status']==='duplicate_paid'):?><br><small class="muted">Valor separado para conferência</small><?php endif;?></td><td><?php if($p['refund_id']):?><span class="badge"><?= Security::e(UiVocabulary::refundStatus((string)$p['refund_status'])) ?></span><br><small><?= Security::e($p['refund_reason']??'') ?></small><?php if(Auth::can('refunds.manage')&&$p['refund_status']==='provider_pending'):?><form method="post" style="margin-top:6px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="reconcile-refund"><input type="hidden" name="refund_id" value="<?= (int)$p['refund_id'] ?>"><button class="secondary compact">Verificar novamente</button></form><?php elseif(Auth::can('refunds.manage')&&$p['refund_status']==='failed'):?><form method="post" style="margin-top:6px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="refund"><input type="hidden" name="payment_id" value="<?= (int)$p['id'] ?>"><input type="hidden" name="reason" value="<?= Security::e($p['refund_reason']??'Nova tentativa de estorno') ?>"><button class="secondary compact">Tentar novamente</button></form><?php endif;?><?php elseif(Auth::can('refunds.manage')&&in_array($p['status'],['paid','duplicate_paid'],true)):?><?php $duplicate=$p['status']==='duplicate_paid';?><form method="post" onsubmit="return confirm('<?= $duplicate?'Confirmar devolução do pagamento duplicado?':'Confirmar estorno integral deste pagamento?' ?>')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="refund"><input type="hidden" name="payment_id" value="<?= (int)$p['id'] ?>"><input name="reason" maxlength="500" required minlength="5" placeholder="<?= $duplicate?'Pagamento duplicado':'Motivo do estorno' ?>" style="min-width:160px"><button class="secondary compact" style="margin-top:5px"><?= $duplicate?'Devolver duplicado':'Estornar' ?></button></form><?php else:?>—<?php endif;?><?php if(Auth::can('audit.view')):?><details class="technical-details" style="margin-top:6px"><summary>Detalhes para suporte</summary><small>Registro interno #<?= (int)$p['id'] ?><br>Integração: <?= Security::e((string)$p['provider']) ?><br>Referência externa: <?= Security::e($p['provider_payment_id']??'—') ?></small></details><?php endif;?></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="7">Nenhum pagamento encontrado nesta unidade.</td></tr><?php endif;?></tbody></table></div></section>
<?php if(Auth::can('audit.view')):?><details class="technical-details" style="margin-top:12px"><summary>Diagnóstico avançado de pagamentos</summary><section class="card"><div class="alert">Informações técnicas para suporte. Não são necessárias para a operação normal.</div><div class="table-wrap"><table class="table"><thead><tr><th>Integração</th><th>Referência</th><th>Validação</th><th>Situação técnica</th><th>Processado</th></tr></thead><tbody><?php foreach($webhooks as$w):?><tr><td><?= Security::e($w['provider']) ?></td><td><code><?= Security::e($w['external_event_id']) ?></code></td><td><?= $w['signature_valid']?'Válida':'Inválida' ?></td><td><?= Security::e($w['status']) ?></td><td><?= Security::e($w['processed_at']??'—') ?></td></tr><?php endforeach;?></tbody></table></div></section></details><?php endif;?>
<?php em_footer();